class MRUQueue {
    vector<int> values;
public:
    MRUQueue(int n) {
        for (int i = 1; i <= n; ++i) values.push_back(i);
    }
    int fetch(int k) {
        int value = values[k - 1];
        values.erase(values.begin() + k - 1);
        values.push_back(value);
        return value;
    }
};
